    'Questions about RdyDeck': 'Fragen zu RdyDeck',
    'What is RdyDeck?': 'Was ist RdyDeck?',
    'RdyDeck is a free web app for Pokémon Trading Card Game players. It grades a 60 card deck, shows its opening odds and which cards rotate out of Standard, and trains you to work out your prize cards.': 'RdyDeck ist eine kostenlose Web-App für Spieler des Pokémon-Sammelkartenspiels. Sie bewertet ein Deck mit 60 Karten, zeigt seine Startchancen und welche Karten aus dem Standardformat rotieren, und trainiert dich darin, deine Preiskarten herauszufinden.',
    'How does prize card training work?': 'Wie funktioniert das Preiskarten-Training?',
    'RdyDeck sets some cards from your deck aside as prizes, 6 by default or 4 or 8, and you flip through the rest. Then you name the cards that are missing. You can add a time limit, and after a few games RdyDeck shows which cards you miss most.': 'RdyDeck legt einige Karten deines Decks als Preiskarten beiseite, standardmäßig 6, oder 4 oder 8, und du blätterst durch den Rest. Dann nennst du die fehlenden Karten. Du kannst ein Zeitlimit setzen, und nach ein paar Runden zeigt RdyDeck, welche Karten du am häufigsten verpasst.',
    'How does the deck grade work?': 'Wie funktioniert die Deck-Note?',
    'The grade is out of 10. Synergy checks that the cards support each other: attackers can pay for their attacks, evolutions have what they evolve from, and the deck can draw and search. Power checks that the plan can win: how hard it hits, how many prizes it gives up and how fast it sets up. The grade is Synergy times Power, divided by 10, so the weaker one pulls the grade down. One part of Synergy, how tightly the list fits together, lowers the grade only when the fit is loose, so a focused list can grade a little above Synergy times Power. When the deck matches an archetype from recent online and local in-person tournaments, part of the grade, up to half once it has 250 games, comes from that archetype\'s results. Each grade shows its own math and comes with a short list of what to fix first.': 'Die Note geht bis 10. Synergie prüft, ob die Karten sich gegenseitig stützen: Angreifer können ihre Attacken bezahlen, Entwicklungen haben ihre Vorstufe, und das Deck kann ziehen und suchen. Stärke prüft, ob der Plan gewinnen kann: wie hart er trifft, wie viele Preiskarten er abgibt und wie schnell er aufbaut. Die Note ist Synergie mal Stärke, geteilt durch 10, also zieht der schwächere Wert die Note nach unten. Ein Teil der Synergie, wie eng die Liste zusammenpasst, senkt die Note nur, wenn sie locker ist, also kann eine fokussierte Liste etwas über Synergie mal Stärke liegen. Passt das Deck zu einem Archetyp aus aktuellen Online- und lokalen Präsenzturnieren, stammt ein Teil der Note, bis zur Hälfte ab 250 Spielen, aus den Ergebnissen dieses Archetyps. Jede Note zeigt ihre Rechnung und eine kurze Liste, was du zuerst beheben solltest.',
    'How does the rotation check work?': 'Wie funktioniert der Rotations-Check?',
    'RdyDeck reads each card\'s regulation mark and shows which cards are not Standard legal now, which may rotate next, and which are safe. A card counts as safe only when its mark is confirmed, and a deck with cards that are not legal now grades 4.9 at most. An older printing still counts when a reprint with the same name, attacks and Abilities is legal now, so old art is fine.': 'RdyDeck liest das Regelzeichen jeder Karte und zeigt, welche Karten jetzt nicht im Standardformat legal sind, welche als Nächstes rotieren könnten und welche sicher sind. Eine Karte gilt nur als sicher, wenn ihr Zeichen bestätigt ist, und ein Deck mit derzeit nicht legalen Karten bekommt höchstens 4.9. Ein älterer Druck zählt weiter, wenn ein Nachdruck mit gleichem Namen, gleichen Attacken und Fähigkeiten jetzt legal ist, alte Artworks sind also in Ordnung.',
    'Which deck lists can I import?': 'Welche Decklisten kann ich importieren?',
    'Paste an export from Pokémon TCG Live or a list from Limitless TCG, one card per line with the count, name, set code and number. Starter decks are built in if you want to try it first.': 'Füge einen Export aus Pokémon TCG Live oder eine Liste von Limitless TCG ein, eine Karte pro Zeile mit Anzahl, Name, Set-Kürzel und Nummer. Starterdecks sind eingebaut, falls du es erst ausprobieren willst.',
    'Is RdyDeck free? Do I need an account?': 'Ist RdyDeck kostenlos? Brauche ich ein Konto?',
    'RdyDeck is free and has no account. Your decks stay in your browser on your own device, it works offline once it has loaded, and you can install it to your home screen.': 'RdyDeck ist kostenlos und braucht kein Konto. Deine Decks bleiben im Browser auf deinem eigenen Gerät, die App funktioniert nach dem Laden offline und du kannst sie auf deinem Startbildschirm installieren.',
    'Unofficial fan-made app. Not affiliated with Nintendo, Creatures, GAME FREAK or The Pokémon Company. Card names, text and images are © The Pokémon Company, Nintendo, Creatures and GAME FREAK.': 'Inoffizielle Fan-App. Nicht verbunden mit Nintendo, Creatures, GAME FREAK oder The Pokémon Company. Kartennamen, Texte und Bilder sind © The Pokémon Company, Nintendo, Creatures und GAME FREAK.',
