    'RdyDeck is an unofficial, fan-made app. It is not produced, endorsed, supported or affiliated with Nintendo, The Pokémon Company, Game Freak or Creatures. Pokémon, card names, card text and card images are trademarks and copyright of their respective owners.': 'RdyDeck ist eine inoffizielle Fan-App. Sie wird nicht von Nintendo, The Pokémon Company, Game Freak oder Creatures produziert, unterstützt oder gefördert und ist nicht mit ihnen verbunden. Pokémon, Kartennamen, Kartentexte und Kartenbilder sind Marken und urheberrechtlich geschützt durch ihre jeweiligen Inhaber.',
