    'This opens an email to us in your own email app, with the details filled in. Nothing is sent until you press Send there. Under 13? Ask a parent to send it.': 'Das öffnet eine E-Mail an uns in deiner eigenen Mail-App, mit den Details schon ausgefüllt. Nichts wird gesendet, bis du dort auf Senden tippst. Unter 13? Bitte deine Eltern, sie zu senden.',
