    'This sends your message straight to us. Please leave out your name and contact details. Under 13? Ask a parent to send it.': 'Damit geht deine Nachricht direkt an uns. Lass bitte deinen Namen und deine Kontaktdaten weg. Unter 13? Bitte deine Eltern, sie zu senden.',
