    'Could not copy. Write to support@rdydeck.com.': 'Kopieren hat nicht geklappt. Schreib an support@rdydeck.com.',
    'Added: how each Trainer works in your deck': 'Neu: wie jeder Trainer in deinem Deck wirkt',
    'Every card now gets a label': 'Jede Karte bekommt jetzt eine Einstufung',
    'Changed: easier to read Goldfish and puzzle boards': 'Geändert: Goldfish- und Puzzle-Felder leichter lesbar',
    'Added: How to improve your deck guide': 'Neu: Guide zum Verbessern deines Decks',
    'Search and AI assistant updates': 'Updates für Suchmaschinen und KI-Assistenten',
    'Deck guides refreshed': 'Deck-Guides aktualisiert',
    'Welcome to RdyDeck': 'Willkommen bei RdyDeck',
    'Grade any Pokémon TCG deck: how well the cards work together, whether it can win, and what to fix first. Then practice it.': 'Bewerte jedes Pokémon-TCG-Deck: wie gut die Karten zusammenpassen, ob es gewinnen kann und was du zuerst beheben solltest. Dann übe es.',
    'Add a deck': 'Deck hinzufügen',
    'Paste a list from Pokémon TCG Live or Limitless, or load one of the starter decks from recent Regionals in one tap.': 'Füge eine Liste aus Pokémon TCG Live oder Limitless ein, oder lade mit einem Fingertipp eines der Starterdecks von aktuellen Regionals.',
    'Read the grade': 'Lies die Note',
    'Tap a deck to open its grade. Fix first lists what costs you the most, and Rotation shows which cards leave Standard next.': 'Tippe auf ein Deck, um seine Note zu öffnen. Zuerst beheben zeigt, was dich am meisten kostet, und Rotation zeigt, welche Karten als Nächstes das Standardformat verlassen.',
    'Check the odds': 'Prüfe die Chancen',
    'Odds answers your own question, like Arven and a Ball by turn 2, and shows your opening Basics.': 'Chancen beantwortet deine eigene Frage, etwa Arven und ein Ball bis Zug 2, und zeigt deine Basis-Pokémon zum Start.',
    'Practice': 'Üben',
    'Learn': 'Lernen',
    'Prizes on a deck starts a prize game: six cards go face down and you name them. The Hand, Drills and Notes tabs hold opening hands, goldfish turns, drills and matchup notes.': 'Preiskarten an einem Deck startet ein Preiskartenspiel: Sechs Karten liegen verdeckt und du nennst sie. Die Tabs Hand, Übungen und Notizen enthalten Starthände, Goldfish-Züge, Übungen und Matchup-Notizen.',
    'Come back daily': 'Komm täglich wieder',
    'Prize Check is the same shuffle for everyone each day. Log your matches in the tournament log. Help on the home screen replays this tour.': 'Der Preiskarten-Check ist jeden Tag für alle gleich gemischt. Trag deine Matches im Turnier-Log ein. Hilfe auf dem Startbildschirm zeigt diese Tour erneut.',
    'Paste my list': 'Liste einfügen',
    'Play a prize game': 'Spiel ein Preiskartenspiel',
    'Study your deck': 'Studiere dein Deck',
    'Import your deck': 'Importiere dein Deck',
    'Paste your Limitless TCG 60 card list and the app builds your card gallery automatically.': 'Füge deine Liste mit 60 Karten von Limitless TCG ein und die App baut deine Kartengalerie automatisch.',
    'Flip through the visible cards': 'Blättere durch die sichtbaren Karten',
    'Swipe left and right. Some cards are secretly set aside as prizes before you start.': 'Wische nach links und rechts. Vor dem Start werden heimlich einige Karten als Preiskarten beiseitegelegt.',
    'Guess every prize card': 'Errate jede Preiskarte',
    'Type your guesses with autocomplete, then tap Reveal prizes.': 'Gib deine Tipps ein (mit Autovervollständigung) und tippe dann auf Preiskarten aufdecken.',
    'Challenge modes': 'Herausforderungsmodi',
    'Tap Modes on a deck to change the prize count (4, 6 or 8), add a time limit, or both.': 'Tippe an einem Deck auf Modi, um die Zahl der Preiskarten zu ändern (4, 6 oder 8), ein Zeitlimit zu setzen, oder beides.',
    'Track weak spots': 'Schwachstellen verfolgen',
    'After 3 sessions the app shows which cards you miss most often, so you know what to focus on.': 'Nach 3 Runden zeigt die App, welche Karten du am häufigsten verpasst, damit du weißt, worauf du achten musst.',
    'Practice openings and share lists': 'Starthände üben und Listen teilen',
    'Open a deck and use the Hand tab to drill turn 1 lines. The link button at the top gives you a link that opens the list in RdyDeck.': 'Öffne ein Deck und übe im Tab Hand deinen ersten Zug. Der Link-Button oben gibt dir einen Link, der die Liste in RdyDeck öffnet.',
    'Goldfish, drills and notes': 'Goldfish, Übungen und Notizen',
    'Each has its own tab on a deck. Hand can goldfish your first three turns, and Sparring plays five turns against a computer opponent with a tournament deck or your own. Drills has resource counts and an opponent prize read. Notes keeps matchup plans, an edit log of every card change, and a compare view. Card art you have seen is saved for offline play.': 'Jedes hat einen eigenen Tab im Deck. Hand kann deine ersten drei Züge goldfishen, und Sparring spielt fünf Züge gegen einen Computergegner mit einem Turnierdeck oder deinem eigenen. Unter Übungen findest du Ressourcen zählen und Gegner-Preiskarten lesen. Notizen speichert Matchup-Pläne, ein Log jeder Kartenänderung und eine Vergleichsansicht. Kartenbilder, die du gesehen hast, werden zum Offline-Spielen gespeichert.',
    'Top finishes for the most played decks at big online tournaments, not Regionals. Lists as of 15 Nov 2026. Load one to start practicing right away, then edit it to match your own build.': 'Top-Platzierungen der meistgespielten Decks bei großen Online-Turnieren, nicht Regionals. Listen mit Stand 15. Nov. 2026. Lade eine, um sofort zu üben, und passe sie dann an deine eigene Version an.',
