    'Tournament Strength': 'Turnierstärke',
    'How decks like it do at events': 'Wie ähnliche Decks bei Turnieren abschneiden',
    'Your cards score higher than decks like this do at events. Card Strength reads only the cards, like how hard they hit and how they trade prizes, not matchups or the field.': 'Deine Karten schneiden besser ab als ähnliche Decks bei Turnieren. Die Kartenstärke liest nur die Karten, etwa wie hart sie treffen und wie sie Preiskarten tauschen, nicht Matchups oder das Meta.',
    'Decks like this do better at events than the cards alone show. Card Strength reads only the cards, like how hard they hit and how they trade prizes, not matchups or the field.': 'Ähnliche Decks schneiden bei Turnieren besser ab, als die Karten allein zeigen. Die Kartenstärke liest nur die Karten, etwa wie hart sie treffen und wie sie Preiskarten tauschen, nicht Matchups oder das Meta.',
    'Fewer than 20 event games': 'Weniger als 20 Turnierspiele',
    'No event results match': 'Keine passenden Turnierergebnisse',
    'N/A': 'k. A.',
    'Share grade': 'Note teilen',
    'Right now Synergy is what holds it back.': 'Im Moment bremst die Synergie die Note.',
    'Right now Power is what holds it back.': 'Im Moment bremst die Stärke die Note.',
    'Fix first': 'Zuerst beheben',
    'The problem that costs you the most.': 'Das Problem, das dich am meisten kostet.',
    'Stops the deck': 'Blockiert das Deck',
    'Worth fixing': 'Lohnt sich',
    'Minor': 'Gering',
    'Nothing to fix': 'Nichts zu beheben',
    'Nothing else to fix': 'Sonst nichts zu beheben',
    'The grader found no problem in this list.': 'Der Bewerter hat in dieser Liste kein Problem gefunden.',
    'Apart from the deck rules above, the grader found no problem in this list.': 'Abgesehen von den Deckregeln oben hat der Bewerter in dieser Liste kein Problem gefunden.',
    'Check the odds and the rotation below before an event.': 'Prüfe vor einem Event die Chancen und die Rotation unten.',
    'Working well': 'Läuft gut',
    'How the grade works': 'So funktioniert die Note',
    'under 3': 'unter 3',
    'checks that your cards support each other: every attacker can pay for its attacks, evolutions have what they evolve from, and the deck can draw and search.': 'prüft, ob deine Karten sich gegenseitig stützen: Jeder Angreifer kann seine Attacken bezahlen, Entwicklungen haben ihre Vorstufe, und das Deck kann ziehen und suchen.',
    'checks that the plan can win: how hard it hits against the format\'s biggest Pokemon, how many prizes it gives up, and how fast it sets up.': 'prüft, ob der Plan gewinnen kann: wie hart er gegen die größten Pokémon des Formats trifft, wie viele Preiskarten er abgibt und wie schnell er aufbaut.',
    'The card grade is Synergy times Power, divided by 10. How tightly the list fits together lowers Synergy in full, but lowers the grade only when the fit is loose. When your deck matches an archetype from recent online and local in-person tournaments, part of the grade comes from that archetype\'s win rate and finishes: more of it the more games there are, up to half at 250 games, and none while cards are not Standard legal. The sentence under the grade shows how much. Card roles are read from card text, which is usually right and sometimes not. Read the findings and do not worry about the decimal place.': 'Die Kartennote ist Synergie mal Stärke, geteilt durch 10. Wie eng die Liste zusammenpasst, senkt die Synergie voll, die Note aber nur, wenn sie locker ist. Passt dein Deck zu einem Archetyp aus aktuellen Online- und lokalen Präsenzturnieren, stammt ein Teil der Note aus Siegquote und Platzierungen dieses Archetyps: umso mehr, je mehr Spiele es gibt, bis zur Hälfte bei 250 Spielen, und nichts, solange Karten nicht im Standardformat legal sind. Der Satz unter der Note zeigt, wie groß dieser Anteil ist. Kartenrollen werden aus dem Kartentext gelesen, was meist stimmt und manchmal nicht. Lies die Befunde und mach dir keine Sorgen um die Nachkommastelle.',
    'No card data for this deck yet.': 'Noch keine Kartendaten für dieses Deck.',
    'These could not be looked up, so they count for nothing in the grade. Opening the deck again while online tries again.': 'Diese konnten nicht abgefragt werden und zählen deshalb nicht zur Note. Öffnest du das Deck online erneut, wird es noch einmal versucht.',
    'Grade history': 'Notenverlauf',
    'Upgrades': 'Verbesserungen',
    "Upgrades show once the list follows the deck rules. Fix first says what to change.": "Verbesserungen erscheinen, sobald die Liste die Deckregeln einhält. „Zuerst beheben“ zeigt, was zu ändern ist.",
    "Upgrades show once every card in the list is Standard legal.": "Verbesserungen erscheinen, sobald jede Karte der Liste Standard-legal ist.",
    "Upgrades show once the card data for this list has loaded.": "Verbesserungen erscheinen, sobald die Kartendaten dieser Liste geladen sind.",
    "Upgrades could not be worked out for this list just now. Open the deck again to retry.": "Die Verbesserungen für diese Liste ließen sich gerade nicht ermitteln. Öffne das Deck erneut, um es noch einmal zu versuchen.",
    'Upgrades need a connection the first time, to read the cards to try.': 'Verbesserungen brauchen beim ersten Mal eine Verbindung, um die Testkarten zu laden.',
    'Upgrades could not read the cards to try yet. School or work wifi can block card data. They are tried again when you open this deck.': 'Verbesserungen konnten die Testkarten noch nicht laden. WLAN in Schule oder Firma kann Kartendaten blockieren. Sie werden erneut versucht, wenn du dieses Deck öffnest.',
    'Checking which card swaps raise this grade.': 'Es wird geprüft, welcher Kartentausch diese Note hebt.',
    "No single swap raises this grade, its Synergy or its Power.": "Kein einzelner Kartentausch hebt diese Note, ihre Synergie oder ihre Stärke.",
    "What Fix first lists needs more than one card changed.": "Was „Zuerst beheben“ nennt, braucht mehr als eine geänderte Karte.",
