    'Matches': 'Matches',
    'The line in each bar is 50%. The light band is the likely range from the games so far. Favored and Unfavored need the whole band on one side of 50%.': 'Die Linie in jedem Balken ist 50%. Das helle Band ist der wahrscheinliche Bereich nach den bisherigen Spielen. Favorisiert und Benachteiligt brauchen das ganze Band auf einer Seite von 50%.',
    'All results': 'Alle Ergebnisse',
    'No deck in recent results plays the same Pokemon as this one. Pick the closest deck above to see its matchups.': 'Kein Deck in den aktuellen Ergebnissen spielt dieselben Pokémon wie dieses. Wähle oben das ähnlichste Deck, um seine Matchups zu sehen.',
