    'Mostly two-prize Pokemon': 'Meist Pokémon für zwei Preiskarten',
    'No ACE SPEC': 'Keine ASS-KLASSE',
    'No ACE SPEC. Every deck may run 1, and nearly every top list does.': 'Keine ASS-KLASSE-Karte. Jedes Deck darf 1 spielen, und fast jede Top-Liste tut es.',
    'No Basic Pokémon, so the game cannot start.': 'Kein Basis-Pokémon, daher kann das Spiel nicht starten.',
    'No Pokémon yet.': 'Noch keine Pokémon.',
    'No real draw engine': 'Keine echte Zieh-Engine',
    'No way to find your Pokemon': 'Kein Weg, deine Pokémon zu finden',
    'Nothing to pull up a Benched Pokemon': 'Nichts, um ein Pokémon von der Bank zu holen',
    'Sets up on time': 'Baut rechtzeitig auf',
    'Some damage is left out': 'Etwas Schaden fehlt in der Rechnung',
    'Three-prize attackers, two-prize punch': 'Angreifer für drei Preiskarten, Schlagkraft für zwei',
    'Two prizes per knockout': 'Zwei Preiskarten pro K.O.',
    'Every Pokemon here gives up one prize, so the opponent has to take six knockouts.': 'Jedes Pokémon hier gibt eine Preiskarte ab, der Gegner braucht also sechs K.O.s.',
    'No Pokemon here is set up to deal meaningful damage, so there is no win condition to build toward.': 'Kein Pokémon hier ist darauf ausgelegt, nennenswerten Schaden zu machen, also gibt es kein Siegziel, auf das man hinarbeitet.',
    'None of your attackers have the energy they need, so damage output is basically zero.': 'Keiner deiner Angreifer hat die nötige Energie, der Schaden ist also praktisch null.',
    'Your only card that pulls up a Benched Pokemon, which is how you take the prizes you choose.': 'Deine einzige Karte, die ein Pokémon von der Bank holt, so nimmst du die Preiskarten, die du willst.',
    'Switches your Active Pokemon.': 'Tauscht dein Aktives Pokémon aus.',
    'Removes your opponent\'s Energy and gets rid of Pokemon Tools.': 'Entfernt Energie des Gegners und wird Pokémon-Ausrüstung los.',
    "Four card counts then move the card grade a little: cards that draw or search, cards that pay off after one of your Pokemon is Knocked Out, cards that cut damage, and cards that pull up a Benched Pokemon. Each was kept only because it brought grades closer to tournament results.": "Danach verschieben vier Kartenzählungen die Kartennote ein wenig: Karten, die ziehen oder suchen, Karten, die sich lohnen, nachdem eines deiner Pokémon kampfunfähig wurde, Karten, die Schaden verringern, und Karten, die ein Pokémon von der Bank in die Aktive Position holen. Jede blieb nur, weil sie die Noten näher an die Turnierergebnisse brachte.",
    "Draw and search": "Ziehen und Suchen",
    'Synergy: how the cards fit': 'Synergie: wie die Karten passen',
    'Good': 'Gut',
    'Key': 'Schlüsselkarte',
    'Weak': 'Schwach',
    'Dead': 'Tot',
    'Fine': 'Okay',
    'In this deck:': 'In diesem Deck:',
    'RdyDeck hasn\'t read this card\'s text yet, so it has no label. Open the deck online to read it.': 'RdyDeck hat den Text dieser Karte noch nicht gelesen, daher hat sie keine Einstufung. Öffne das Deck online, um ihn zu lesen.',
    'Mulligan': 'Mulligan',
    'Opening 7 with no Basic': 'Starthand ohne Basis-Pokémon',
    'Draw card T1': 'Ziehkarte Z1',
    'A draw card you can use, in your first 8': 'Eine nutzbare Ziehkarte in deinen ersten 8',
    'Attacker by T2, any hand': 'Angreifer bis Z2, jede Hand',
    'No attacker line read': 'Keine Angreiferlinie erkannt',
    'Ask the odds': 'Frag die Chancen',
    'Pick the cards you need and the turn. Exact counting for this list: a hand with no Basic is redrawn, so only hands you keep count, and both players draw on their first turn.': 'Wähle die Karten, die du brauchst, und den Zug. Exakte Rechnung für diese Liste: Eine Hand ohne Basis-Pokémon wird neu gezogen, es zählen also nur Hände, die du behältst, und beide Spieler ziehen in ihrem ersten Zug.',
    'At least': 'Mindestens',
    'of': 'von',
    'or': 'oder',
    'And another card': 'Und noch eine Karte',
    'By': 'Bis',
    'Stuck in prizes: 0.0%': 'In Preiskarten fest: 0.0%',
    'Games where the prizes hold so many copies that hand and deck cannot make this until you take the right prize. The same on every turn.': 'Spiele, in denen die Preiskarten so viele Kopien halten, dass Hand und Deck das nicht schaffen, bis du die richtige Preiskarte nimmst. In jedem Zug gleich.',
    'No Basic Pokemon was read in this list, so every opening hand counts.': 'In dieser Liste wurde kein Basis-Pokémon erkannt, daher zählt jede Starthand.',
    'Raw draws only: search and draw cards are not played out, so a real game lands at or above these numbers.': 'Nur reines Ziehen: Such- und Ziehkarten werden nicht ausgespielt, ein echtes Spiel liegt also bei diesen Werten oder darüber.',
    'No Basic Pokémon read': 'Kein Basis-Pokémon erkannt',
    'No card in this list was read as a Basic Pokemon, so mulligan odds cannot be counted. If the list has Basics, re-saving the deck retries the lookup.': 'Keine Karte dieser Liste wurde als Basis-Pokémon erkannt, daher lassen sich Mulligan-Chancen nicht berechnen. Hat die Liste Basis-Pokémon, versucht erneutes Speichern des Decks die Abfrage noch einmal.',
    'Prize risk': 'Preiskarten-Risiko',
    'Exact chance a card lands in your six prizes, counting only opening hands you keep.': 'Exakte Chance, dass eine Karte in deinen sechs Preiskarten landet, nur mit Starthänden, die du behältst.',
    'All prized': 'Alle in Preiskarten',
    'means every copy is stuck there, which is the case RdyDeck drills you to spot.': 'heißt, jede Kopie steckt dort fest, genau der Fall, den du mit RdyDeck erkennen lernst.',
    'Card': 'Karte',
    'Copies': 'Kopien',
    'Any prized': 'Eine in Preiskarten',
    'What this does not do.': 'Was das nicht kann.',
    'Matchup win rates are not here. They are on the Grade tab, in Against the meta, from recent online and local in-person tournaments. Everything on this tab comes from shuffling your own list.': 'Siegquoten pro Matchup stehen nicht hier. Sie stehen im Tab Note unter Gegen das Meta, aus aktuellen Online- und lokalen Präsenzturnieren. Alles in diesem Tab kommt vom Mischen deiner eigenen Liste.',
    'Opening Basics': 'Basis-Pokémon zum Start',
    'In opening hand': 'Starthand',
    'Attacker': 'Angreifer',
    'This list is too short to simulate.': 'Diese Liste ist zu kurz für eine Simulation.',
    'Odds need at least 15 cards: an opening hand, six prizes and two draws.': 'Chancen brauchen mindestens 15 Karten: eine Starthand, sechs Preiskarten und zwei gezogene Karten.',
    'Games where every copy of a piece the attacker needs is prized, so it cannot come online until you take that prize.': 'Spiele, in denen jede Kopie eines Teils, das der Angreifer braucht, in den Preiskarten liegt, er kann also erst loslegen, wenn du diese Preiskarte nimmst.',
    'Pick cards': 'Karten wählen',
    'Pick a card to see how often you have it.': 'Wähle eine Karte, um zu sehen, wie oft du sie hast.',
    'No card data yet, so mulligans are not taken out. Open Edit deck and save it to read the cards.': 'Noch keine Kartendaten, daher werden Mulligans nicht abgezogen. Öffne Deck bearbeiten und speichere, um die Karten zu lesen.',
    'Tick one card, or several. With several, pick how they count.': 'Hake eine Karte an, oder mehrere. Bei mehreren wähle, wie sie zählen.',
    'Any of them (or)': 'Eine davon (oder)',
    'Every one (and)': 'Jede (und)',
    'Core': 'Kern',
