    'Goldfish (3 Turns)': 'Goldfish (3 Züge)',
    'Sparring (5 Turns)': 'Sparring (5 Züge)',
    'Sparring': 'Sparring',
    'Opening hand': 'Starthand',
    'A random 7 from this list. Pick the line you would build on turn 1, lock it in, then see how often it comes together.': 'Zufällige 7 aus dieser Liste. Wähle die Linie, die du in Zug 1 aufbauen würdest, leg sie fest und sieh dann, wie oft sie klappt.',
