    'The prizes and draws this shuffle actually gave you. Highlighted cards are pieces of your line.': 'Die Preiskarten und gezogenen Karten, die dir dieses Mischen tatsächlich gab. Markierte Karten sind Teile deiner Linie.',
    'Turn 1 and 2 draws': 'Ziehen in Zug 1 und 2',
    'Turn 3 draw': 'Ziehen in Zug 3',
    'What this counts.': 'Was das zählt.',
    'Search cards each fetch one missing piece if a copy is still in the deck. Draw Supporters, abilities, discard costs and the one Supporter per turn rule are not played out, the same as the Odds tab. Play this hand in Goldfish plays them out turn by turn, with the same prizes and draws.': 'Suchkarten holen je ein fehlendes Teil, wenn noch eine Kopie im Deck ist. Zieh-Unterstützer, Fähigkeiten, Ablagekosten und die Regel von einem Unterstützer pro Zug werden nicht ausgespielt, wie im Tab Chancen. Im Goldfish spielen spielt sie Zug für Zug aus, mit denselben Preiskarten und gezogenen Karten.',
