    'Goldfish rules.': 'Goldfish-Regeln.',
    "Tap a card in your hand to play it. Tap a Pokémon in play to retreat, use its Ability or attack. An attack ends your turn.": "Tippe auf eine Karte auf deiner Hand, um sie zu spielen. Tippe auf ein Pokémon im Spiel, um es zurückzuziehen, seine Fähigkeit einzusetzen oder anzugreifen. Eine Attacke beendet deinen Zug.",
    "Add a damage counter": "Eine Schadensmarke hinzufügen",
    "Remove a damage counter": "Eine Schadensmarke entfernen",
    "No damage on it": "Kein Schaden",
    "Attacks start on turn 1.": "Attacken beginnen in Zug 1.",
    "Your turn has ended.": "Dein Zug ist zu Ende.",
    "Only your Active Pokémon can attack.": "Nur dein Aktives Pokémon kann angreifen.",
    "The player going first cannot attack on turn 1.": "Wer beginnt, kann in Zug 1 nicht angreifen.",
    "Not enough Energy attached.": "Nicht genug Energie angelegt.",
    "It cannot use this attack this turn, because of the attack it used last turn.": "Es kann diese Attacke in diesem Zug nicht einsetzen, wegen der Attacke aus dem letzten Zug.",
    "No attack text read yet. Open this deck online to read it.": "Attackentext noch nicht gelesen. Öffne dieses Deck online, um ihn zu lesen.",
    "No card text read yet. Open this deck online to read it.": "Kartentext noch nicht gelesen. Öffne dieses Deck online, um ihn zu lesen.",
    "The app cannot follow all of this attack yet, so you finish it by hand.": "Die App kann dieser Attacke noch nicht ganz folgen, also beendest du sie von Hand.",
    "The app cannot follow this card's text yet, so playing it lets you do it by hand.": "Die App kann dem Text dieser Karte noch nicht folgen, also spielst du sie und erledigst es von Hand.",
    "During setup only Basic Pokémon go into play.": "Beim Aufbau kommen nur Basis-Pokémon ins Spiel.",
    "Nothing to do with this card now.": "Mit dieser Karte ist gerade nichts zu tun.",
    "Make Active and play on in Goldfish": "Aktiv machen und in Goldfish weiterspielen",
    "Only Basic Pokémon go into play before turn 1. Tap a Basic to play this hand on in Goldfish.": "Vor Zug 1 kommen nur Basis-Pokémon ins Spiel. Tippe auf ein Basis-Pokémon, um diese Hand in Goldfish weiterzuspielen.",
    "On schedule": "Im Zeitplan",
    "A turn behind": "Einen Zug zu spät",
    "You draw every turn, one Energy and one Supporter a turn, no Supporter and no attack on turn 1 going first, and no evolving on your first turn or onto a Pokémon that came in this turn. Abilities, attacks, Items, Supporters and Stadiums do what their card text says, with each card's own limits, and an attack ends your turn. Damage stays on your Pokémon, and a Pokémon is Knocked Out when its damage reaches its HP. There is no opponent, so effects on your opponent do nothing here. When the app cannot follow a card yet, it shows the text and you use Draw, Search, Discard and the damage counter buttons.": "Du ziehst jeden Zug, eine Energie und ein Unterstützer pro Zug, kein Unterstützer und keine Attacke in Zug 1, wenn du beginnst, und keine Entwicklung in deinem ersten Zug oder auf ein Pokémon, das in diesem Zug kam. Fähigkeiten, Attacken, Items, Unterstützer und Stadien tun, was ihr Kartentext sagt, mit den Grenzen jeder Karte, und eine Attacke beendet deinen Zug. Schaden bleibt auf deinen Pokémon, und ein Pokémon ist kampfunfähig, wenn sein Schaden seine KP erreicht. Es gibt keinen Gegner, also bewirken Effekte auf den Gegner hier nichts. Kann die App einer Karte noch nicht folgen, zeigt sie den Text und du nutzt Ziehen, Suchen, Ablegen und die Schaltflächen für Schadensmarken.",
