    'Each player gets a Build and Battle Box:': 'Jeder Spieler bekommt eine Build and Battle Box:',
    'Deck rules': 'Deckregeln',
    'Exactly 40 cards.': 'Genau 40 Karten.',
    'Any number of copies of a card.': 'Beliebig viele Kopien einer Karte.',
    'Each player takes 4 prize cards, not 6.': 'Jeder Spieler nimmt 4 Preiskarten, nicht 6.',
    'The store has extra Basic Energy to add.': 'Der Laden hat extra Basis-Energie zum Hinzufügen.',
    'Build a practice 40': 'Übungsdeck mit 40 bauen',
    'Tap a card to add a copy. Save it, then practice it like any deck. Prize games use 4 prizes.': 'Tippe auf eine Karte, um eine Kopie hinzuzufügen. Speichere und übe es wie jedes Deck. Preiskartenspiele nutzen 4 Preiskarten.',
    'Secret rares': 'Secret Rares',
    'Loading the set…': 'Set wird geladen…',
    'Prerelease check': 'Prerelease-Check',
    'What is in it': 'Was drin ist',
    'Evolutions': 'Entwicklungen',
    'The 0 to 10 grade is built for 60 card Standard decks, so prerelease decks get this check instead.': 'Die Note von 0 bis 10 ist für Standard-Decks mit 60 Karten gebaut, daher bekommen Prerelease-Decks stattdessen diesen Check.',
    'Prize games work with 4 prizes. Tap Play to start one.': 'Preiskartenspiele laufen mit 4 Preiskarten. Tippe auf Spielen, um eins zu starten.',
    'Prerelease deck': 'Prerelease-Deck',
    'Add some cards first.': 'Füge zuerst ein paar Karten hinzu.',
    'Prerelease decks have a build check, not a grade to share.': 'Prerelease-Decks haben einen Bau-Check, keine Note zum Teilen.',
    'Install': 'Installieren',
    '✓ App installed!': '✓ App installiert!',
