    'Each card\'s price and your list\'s total, from TCGdex, with a cheapest first option.': 'Der Preis jeder Karte und die Summe deiner Liste, von TCGdex, mit einer Option für die günstigsten zuerst.',
    'Added: how accurate the grades are': 'Neu: wie genau die Noten sind',
    'Each week, how closely grades rank decks against their real online win rates, per set.': 'Jede Woche, wie gut die Noten Decks im Vergleich zu ihren echten Online-Siegquoten ordnen, pro Set.',
    'Added: This grade looks off?': 'Neu: Note wirkt falsch?',
    'Tell us when a grade seems wrong, with one tap and no typing.': 'Sag uns mit einem Fingertipp, ohne etwas zu schreiben, wenn eine Note falsch wirkt.',
    'Added: Against the field now': 'Neu: Gegen das aktuelle Feld',
    'Your deck\'s expected win rate against the decks people play most right now.': 'Die erwartete Siegquote deines Decks gegen die Decks, die gerade am meisten gespielt werden.',
    'Added: How did it do?': 'Neu: Wie lief es?',
    'Save your record from an event next to the grade your list had then.': 'Speichere deine Bilanz von einem Event neben der Note, die deine Liste damals hatte.',
    'Added: What\'s next': 'Neu: Was kommt',
    'See what is planned and send us your ideas, from Settings or Help.': 'Sieh, was geplant ist, und schick uns deine Ideen, über Einstellungen oder Hilfe.',
    'Added: new set week': 'Neu: Woche des neuen Sets',
    'Home tells you when a new set is out and which decks have cards to check.': 'Start zeigt dir, wenn ein neues Set erscheint und welche Decks Karten zum Prüfen haben.',
    'Changed: clearer win rates and one tap share': 'Geändert: klarere Siegquoten und Teilen mit einem Fingertipp',
    'Both win rates are labeled, and Share grade sends the picture in one tap.': 'Beide Siegquoten sind beschriftet, und Note teilen sendet das Bild mit einem Fingertipp.',
    'Added: error reports': 'Neu: Fehlerberichte',
    'When something breaks, a short report with nothing personal in it helps fix it. You can turn it off in Settings.': 'Wenn etwas kaputtgeht, hilft ein kurzer Bericht ohne persönliche Daten beim Beheben. Du kannst ihn in den Einstellungen ausschalten.',
    'This grade looks off?': 'Note wirkt falsch?',
    'This grade looks off': 'Note wirkt falsch',
    'Pick the closest reason. It is sent without your name or your deck list, and helps make grades match real results.': 'Wähle den passendsten Grund. Er wird ohne deinen Namen und ohne deine Deckliste gesendet und hilft, die Noten an echte Ergebnisse anzupassen.',
