    'Games where the prizes hold so many copies that hand and deck cannot make every line of this question until you take the right prize.': 'Spiele, in denen die Preiskarten so viele Kopien halten, dass Hand und Deck nicht jede Zeile dieser Frage schaffen, bis du die richtige Preiskarte nimmst.',
