  besides: x => `Dieses Deck greift nicht nur an, sondern ${x} auch.`, lists: n => n === '1' ? 'Der Spielplan nennt einen weiteren.' : `Der Spielplan nennt ${n} weitere.`, keep: x => `Halte ${x} in der Aktiven Position`,
